/*
 * Button styling — STEP 1 design tokens ONLY.
 *
 * Every visual value below resolves to a token CSS custom property emitted by
 * the style-dictionary build (dist/themes/<direction>/variables.css). There are
 * ZERO hardcoded hex colors, px sizes, or literal spacing values, so the button
 * re-themes automatically whenever <ThemeProvider> swaps the active direction.
 */

.eda-btn {
  /* layout */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: var(--radius-md);

  /* typography */
  font-family: var(--font-family-sans);
  font-weight: var(--font-weight-semibold);
  line-height: var(--font-line-height-tight);
  letter-spacing: var(--font-letter-spacing-normal);
  text-decoration: none;
  white-space: nowrap;

  /* interaction */
  cursor: pointer;
  user-select: none;
  transition:
    background-color 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease,
    box-shadow 0.15s ease;
}

/* ---- Sizes (padding + font-size mapped onto the spacing/type scales) ---- */
.eda-btn--sm {
  padding: var(--space-1) var(--space-3);
  font-size: var(--font-size-sm);
}
.eda-btn--md {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-base);
}
.eda-btn--lg {
  padding: var(--space-3) var(--space-6);
  font-size: var(--font-size-lg);
}

/* ---- Variant: primary (solid brand) ---- */
.eda-btn--primary {
  background-color: var(--color-semantic-primary-default);
  color: var(--color-semantic-primary-contrast);
  border-color: var(--color-semantic-primary-default);
}
.eda-btn--primary:hover:not(:disabled) {
  background-color: var(--color-semantic-primary-hover);
  border-color: var(--color-semantic-primary-hover);
}
.eda-btn--primary:active:not(:disabled) {
  background-color: var(--color-semantic-primary-active);
  border-color: var(--color-semantic-primary-active);
}

/* ---- Variant: secondary (neutral surface, outlined) ---- */
.eda-btn--secondary {
  background-color: var(--color-semantic-surface-raised);
  color: var(--color-semantic-text-primary);
  border-color: var(--color-semantic-border-default);
}
.eda-btn--secondary:hover:not(:disabled) {
  background-color: var(--color-semantic-surface-sunken);
  border-color: var(--color-semantic-border-strong);
}
.eda-btn--secondary:active:not(:disabled) {
  background-color: var(--color-semantic-surface-sunken);
  border-color: var(--color-semantic-border-strong);
}

/* ---- Variant: danger (destructive) ---- */
.eda-btn--danger {
  background-color: var(--color-semantic-danger-default);
  color: var(--color-semantic-text-inverse);
  border-color: var(--color-semantic-danger-default);
}
.eda-btn--danger:hover:not(:disabled) {
  background-color: var(--color-primitive-red-700);
  border-color: var(--color-primitive-red-700);
}
.eda-btn--danger:active:not(:disabled) {
  background-color: var(--color-primitive-red-700);
  border-color: var(--color-primitive-red-700);
}

/* ---- Focus-visible ring (keyboard accessibility) ---- */
.eda-btn:focus-visible {
  outline: none;
  /* token-driven ring; offset keeps it clear of the button edge */
  box-shadow:
    0 0 0 var(--space-1) var(--color-semantic-border-focus);
}

/* ---- Disabled ---- */
.eda-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

import type { ButtonHTMLAttributes, ReactNode } from 'react';
import './Button.css';

/**
 * Button — the reference token-consuming component for the eda-designs React
 * adapter.
 *
 * It styles itself EXCLUSIVELY through the STEP 1 design-token CSS custom
 * properties (see Button.css). No color/spacing/radius/font value is hardcoded
 * in this component, so it re-themes automatically when <ThemeProvider> swaps
 * the active design direction (e.g. default <-> midnight) — no prop or code
 * change required.
 *
 * Accessibility: renders a real <button>, forwards native button attributes
 * (type, aria-*, onClick, ...), and exposes a token-driven focus-visible ring.
 */

/** Visual intent, each mapped onto semantic color tokens. */
export type ButtonVariant = 'primary' | 'secondary' | 'danger';

/** Size, mapped onto the spacing + type scales. */
export type ButtonSize = 'sm' | 'md' | 'lg';

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual intent. Defaults to `primary`. */
  variant?: ButtonVariant;
  /** Control size. Defaults to `md`. */
  size?: ButtonSize;
  /** Button label / content. */
  children?: ReactNode;
}

/** Join class names, dropping falsy entries. */
function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ');
}

export function Button({
  variant = 'primary',
  size = 'md',
  type = 'button',
  className,
  children,
  ...rest
}: ButtonProps) {
  return (
    <button
      // Default to a non-submitting button so it is safe outside a <form>;
      // callers can still pass type="submit" via props.
      type={type}
      className={cx(
        'eda-btn',
        `eda-btn--${variant}`,
        `eda-btn--${size}`,
        className,
      )}
      {...rest}
    >
      {children}
    </button>
  );
}

export default Button;
